package com.opensocket.aievent.core.a2a.application.service;
import java.time.*;import java.util.*;import org.springframework.transaction.annotation.Transactional;import com.opensocket.aievent.core.a2a.*;import com.opensocket.aievent.core.a2a.application.port.in.A2AUnifiedReconciliationUseCase;
/** Single operational authority for deterministic diagnosis, claiming and governed repair execution. */
public class A2AUnifiedReconciliationService implements A2AUnifiedReconciliationUseCase {
 private static final int MAX_AUTOMATIC_ATTEMPTS=5;private final A2AReconciliationCaseRepository cases;private final A2AReconciliationEvidenceRepository evidence;private final A2ADomainEventPublisher events;
 public A2AUnifiedReconciliationService(A2AReconciliationCaseRepository c,A2AReconciliationEvidenceRepository e,A2ADomainEventPublisher p){cases=c;evidence=e;events=p;}
 @Transactional(readOnly=true) public A2AReconciliationPage search(A2AReconciliationSearchQuery q){if(q==null)throw new IllegalArgumentException("query is required");required(q.tenantId(),"tenantId");return new A2AReconciliationPage(cases.search(q),cases.count(q),q.normalizedOffset(),q.cappedLimit());}
 @Transactional(readOnly=true) public A2AReconciliationDetail detail(String t,String id){A2AReconciliationCase c=find(t,id);return new A2AReconciliationDetail(c,A2ARepairPlanFactory.create(c),evidence.findByCase(t,id,250));}
 @Transactional public A2AReconciliationCase execute(A2ARepairExecutionCommand cmd){required(cmd.tenantId(),"tenantId");required(cmd.caseId(),"caseId");required(cmd.planHash(),"planHash");required(cmd.idempotencyKey(),"idempotencyKey");required(cmd.actorId(),"actorId");required(cmd.reason(),"reason");A2AReconciliationCase c=find(cmd.tenantId(),cmd.caseId());if(c.getVersion()!=cmd.expectedVersion())throw new IllegalStateException("RESOURCE_VERSION_CONFLICT");A2ARepairPlan plan=A2ARepairPlanFactory.create(c);if(!plan.planHash().equals(cmd.planHash()))throw new IllegalStateException("REPAIR_PLAN_STALE");if(c.getStatus()==A2AReconciliationStatus.EXECUTING&&cmd.idempotencyKey().equals(c.getIdempotencyKey()))return c;if(c.getStatus().terminal()||c.getStatus()==A2AReconciliationStatus.WAIT_HUMAN)throw new IllegalStateException("RECONCILIATION_CASE_NOT_EXECUTABLE");long expected=c.getVersion();OffsetDateTime now=now();c.setStatus(A2AReconciliationStatus.EXECUTING);c.setAuthorityOwner(plan.authorityOwner().name());c.setDiagnosisCode(plan.diagnosisCode());c.setRepairAction(plan.action().name());c.setRequiredPermission(plan.requiredPermission());c.setImpactSummary(plan.impactSummary());c.setEvidenceSnapshotHash(plan.evidenceSnapshotHash());c.setPlanHash(plan.planHash());c.setExpectedResourceVersion(plan.expectedResourceVersion());c.setIdempotencyKey(cmd.idempotencyKey());c.setAttemptCount(c.getAttemptCount()+1);c.setUpdatedAt(now);c.setVersion(expected+1);A2AReconciliationCase saved=cases.saveExpectedVersion(c,expected);append(saved,"REPAIR_REQUESTED",cmd.idempotencyKey(),"ACCEPTED","REPAIR_REQUESTED",cmd.reason(),cmd.actorId(),now);events.publish(new A2ADomainEvent("a2a-repair-"+UUID.randomUUID(),A2ADomainEventType.A2A_REPAIR_REQUESTED,saved.getTenantId(),saved.getCaseId(),saved.getRequestId(),saved.getCaseId(),cmd.idempotencyKey(),"OPERATOR",cmd.actorId(),now,1,Map.of("caseId",saved.getCaseId(),"requestId",safe(saved.getRequestId()),"repairAction",safe(saved.getRepairAction()),"authorityOwner",safe(saved.getAuthorityOwner()),"planHash",saved.getPlanHash(),"expectedVersion",saved.getExpectedResourceVersion())));return saved;}
 @Transactional public A2AReconciliationCase recordOutcome(A2ARepairOutcomeCommand cmd){A2AReconciliationCase c=find(cmd.tenantId(),cmd.caseId());if(c.getVersion()!=cmd.expectedVersion())throw new IllegalStateException("RESOURCE_VERSION_CONFLICT");long expected=c.getVersion();OffsetDateTime now=now();if(cmd.succeeded()){c.setStatus(A2AReconciliationStatus.RESOLVED);c.setResolvedBy(first(cmd.actorId(),"AUTHORITY"));c.setResolutionReason(first(cmd.reason(),"Repair authority confirmed completion"));c.setResolvedAt(now);c.setNextAttemptAt(null);c.setLastErrorCode(null);c.setLastError(null);}else if(cmd.retryable()&&c.getAttemptCount()<MAX_AUTOMATIC_ATTEMPTS){c.setStatus(A2AReconciliationStatus.RETRY_WAITING);c.setLastErrorCode(first(cmd.reasonCode(),"REPAIR_FAILED_RETRYABLE"));c.setLastError(cmd.reason());c.setNextAttemptAt(now.plusSeconds(Math.min(900,30L*(1L<<Math.min(c.getAttemptCount(),5)))));}else{c.setStatus(A2AReconciliationStatus.WAIT_HUMAN);c.setLastErrorCode(first(cmd.reasonCode(),"RETRY_EXHAUSTED"));c.setLastError(cmd.reason());c.setNextAttemptAt(null);}c.setRepairEvidenceId(cmd.evidenceReference());c.setClaimedBy(null);c.setClaimTokenHash(null);c.setClaimUntil(null);c.setHeartbeatAt(null);c.setUpdatedAt(now);c.setVersion(expected+1);A2AReconciliationCase saved=cases.saveExpectedVersion(c,expected);String type=cmd.succeeded()?"REPAIR_COMPLETED":"REPAIR_FAILED";append(saved,type,"outcome:"+saved.getCaseId()+":"+expected,cmd.succeeded()?"RESOLVED":saved.getStatus().name(),cmd.reasonCode(),cmd.reason(),cmd.actorId(),now);events.publish(new A2ADomainEvent("a2a-repair-outcome-"+UUID.randomUUID(),cmd.succeeded()?A2ADomainEventType.A2A_REPAIR_COMPLETED:A2ADomainEventType.A2A_REPAIR_FAILED,saved.getTenantId(),saved.getCaseId(),saved.getRequestId(),saved.getCaseId(),cmd.evidenceReference(),"AUTHORITY",first(cmd.actorId(),"AUTHORITY"),now,1,Map.of("caseId",saved.getCaseId(),"status",saved.getStatus().name(),"reasonCode",first(cmd.reasonCode(),"NONE"))));return saved;}
 @Transactional public int reconcileDue(String workerId,int limit){OffsetDateTime now=now();int count=0;for(A2AReconciliationCase c:cases.claimDue(required(workerId,"workerId"),now,now.plusSeconds(60),Math.max(1,Math.min(limit,100)))){A2ARepairPlan p=A2ARepairPlanFactory.create(c);long expected=c.getVersion();c.setStatus(p.action()==A2ARepairAction.WAIT_HUMAN?A2AReconciliationStatus.WAIT_HUMAN:A2AReconciliationStatus.READY);c.setAuthorityOwner(p.authorityOwner().name());c.setDiagnosisCode(p.diagnosisCode());c.setRepairAction(p.action().name());c.setRequiredPermission(p.requiredPermission());c.setImpactSummary(p.impactSummary());c.setEvidenceSnapshotHash(p.evidenceSnapshotHash());c.setPlanHash(p.planHash());c.setExpectedResourceVersion(p.expectedResourceVersion());c.setClaimedBy(null);c.setClaimTokenHash(null);c.setClaimUntil(null);c.setHeartbeatAt(null);c.setUpdatedAt(now);c.setVersion(expected+1);try{A2AReconciliationCase saved=cases.saveExpectedVersion(c,expected);append(saved,"PLAN_PREPARED","plan:"+saved.getCaseId()+":"+saved.getRepairAttemptNo(),"READY",saved.getDiagnosisCode(),"Deterministic repair plan prepared.",workerId,now);count++;}catch(IllegalStateException ignored){/* another node won CAS */}}return count;}
 private void append(A2AReconciliationCase c,String type,String eventKey,String decision,String code,String summary,String actor,OffsetDateTime at){A2AReconciliationEvidence e=new A2AReconciliationEvidence();e.setTenantId(c.getTenantId());e.setEvidenceId("a2are-"+UUID.randomUUID());e.setCaseId(c.getCaseId());e.setRepairAttemptNo(c.getRepairAttemptNo());e.setEventKey(eventKey);e.setEvidenceType(type);e.setEvidenceReference(c.getRepairEvidenceId());e.setEvidenceHash(c.getEvidenceSnapshotHash());e.setDecision(decision);e.setReasonCode(code);e.setSafeSummary(summary);e.setActorId(actor);e.setOccurredAt(at);evidence.append(e);}private A2AReconciliationCase find(String t,String id){return cases.findById(required(t,"tenantId"),required(id,"caseId")).orElseThrow(()->new IllegalArgumentException("A2A Reconciliation Case not found: "+id));}private static OffsetDateTime now(){return OffsetDateTime.now(ZoneOffset.UTC);}private static String required(String v,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required");return v.trim();}private static String first(String a,String b){return a==null||a.isBlank()?b:a;}private static String safe(String v){return v==null?"":v;}
}
